#nullable enable
using System.Diagnostics;
using Alba;
using Campaigns.Contracts;
using Campaigns.Slices.Campaigns;
using Campaigns.Views;
using Marten;
// WaitForNonStaleProjectionDataAsync is an extension in Marten.Events.TestingExtensions. Every doc page
// that uses it shows a bare call with no using, so it reads as an IDocumentStore member — it is not, and
// the compiler's message ("no accessible extension method") does not say where to look. Reflection does.
using Marten.Events;
using Npgsql;
using Shouldly;
using Xunit;
using Xunit.Abstractions;

namespace Campaigns.IntegrationTests;

/// <summary>
/// FIVE VIEWS, SIX MARTEN RECIPES, ONE MODEL — and nothing in the model chooses between them.
///
/// No GWT generates any of these tests, and that is not an oversight in the model. A GWT is
/// GIVEN events / WHEN a command / THEN events, and its <c>when=</c> must name a Command in its own slice —
/// so a view slice cannot have one. Every assertion below is therefore hand-written, which is the honest
/// division: the model can say what a row IS, and only code can say what a recipe COSTS.
///
/// What each test is for:
///
///   1 + 2  self-aggregating snapshot vs. the same fold read LIVE — one file, one fold, one line apart
///   3      EventProjection: one event writes many rows, and what its rebuild does that no other does
///   4      MultiStream across TWO stream types, plus the grouper for events that lack the key
///   5      MultiStream across MANY streams of ONE type, keyed by event METADATA
///   6      FlatTableProjection: a read model that is answered with GROUP BY
/// </summary>
public sealed class ProjectionRecipeTests(AppFixture fixture, ITestOutputHelper output)
    : IntegrationContext(fixture)
{
    private static readonly TimeSpan DaemonTimeout = TimeSpan.FromSeconds(20);
    private static readonly Guid Sender = Guid.Parse("44444444-4444-4444-4444-444444444444");

    // ---------------------------------------------------------------------------------------------
    // Driving the write side through its real endpoints. A projection fed by hand-appended events is
    // not a test of the projection anybody will run in production.
    // ---------------------------------------------------------------------------------------------

    private async Task OpenCampaign(Guid campaignId, string name = "January") =>
        await WhenPosting(x =>
        {
            x.Post.Json(new OpenCampaign(campaignId, name)).ToUrl(OpenCampaignEndpoint.Route);
            x.StatusCodeShouldBe(204);
        });

    private async Task Queue(Guid messageId, Guid campaignId, string[] recipients, Guid? sender = null) =>
        await WhenPosting(x =>
        {
            x.Post.Json(new QueueMessage(
                    messageId, campaignId, sender ?? Sender, "Subject", recipients))
                .ToUrl(QueueMessageEndpoint.Route);
            x.StatusCodeShouldBe(200);
        });

    private async Task Outcome(Guid messageId, string recipient, string outcome) =>
        await WhenPosting(x =>
        {
            x.Post.Json(new RecordOutcome(messageId, recipient, outcome, null))
                .ToUrl($"/messages/{messageId}/outcome");
            x.StatusCodeShouldBe(204);
        });

    // =============================================================================================
    // RECIPES 1 AND 2 — a snapshot, and the identical fold read live
    // =============================================================================================

    /// <summary>
    /// The claim under test: "live aggregation" is not a different projection, it is this projection with
    /// the registration line deleted. If that is true, the stored document and the live fold must be
    /// indistinguishable — so compare them field by field, on a stream with every event type on it.
    /// </summary>
    [Fact]
    public async Task TheStoredSnapshotAndTheLiveFoldAreTheSameValue()
    {
        var campaignId = Guid.NewGuid();
        var messageId = Guid.NewGuid();
        await OpenCampaign(campaignId);
        await Queue(messageId, campaignId, ["a@x.com", "b@x.com"]);
        await Outcome(messageId, "a@x.com", RecordOutcomeEndpoint.Delivered);
        await Outcome(messageId, "b@x.com", RecordOutcomeEndpoint.Bounced);

        await using var session = Store.LightweightSession();

        // Registered: Projections.Snapshot<MessageStatus>(Inline). A row, loaded by id.
        var stored = await session.LoadAsync<MessageStatus>(messageId);

        // Not registered anywhere: the events, folded in memory, right now.
        var live = await session.Events.AggregateStreamAsync<MessageStatus>(messageId);

        stored.ShouldNotBeNull();
        live.ShouldNotBeNull();
        live.ShouldBe(stored);   // records compare by value, so this is every field at once

        stored.RecipientCount.ShouldBe(2);
        stored.Delivered.ShouldBe(1);
        stored.Bounced.ShouldBe(1);
        stored.Status.ShouldBe(MessageStatus.Complete);
    }

    /// <summary>
    /// What INLINE buys, and the reason it is this kit's default: the row is written in the append's own
    /// transaction, so it is there the instant the request returns. No wait, no daemon, no polling — which
    /// is what makes a GWT's THEN assertable at all. Contrast the Async test further down.
    /// </summary>
    [Fact]
    public async Task AnInlineViewIsReadableTheMomentTheWriteReturns()
    {
        var campaignId = Guid.NewGuid();
        var messageId = Guid.NewGuid();
        await OpenCampaign(campaignId);
        await Queue(messageId, campaignId, ["a@x.com"]);

        await using var session = Store.QuerySession();
        (await session.LoadAsync<MessageStatus>(messageId)).ShouldNotBeNull();
    }

    // =============================================================================================
    // RECIPE 3 — EventProjection: one event, many rows
    // =============================================================================================

    /// <summary>
    /// The capability no aggregation has. Three recipients on ONE MessageQueued produce three documents,
    /// and their ids are composed by the projection rather than taken from a stream.
    /// </summary>
    [Fact]
    public async Task OneEventWritesOneRowPerRecipient()
    {
        var campaignId = Guid.NewGuid();
        var messageId = Guid.NewGuid();
        string[] recipients = ["a@x.com", "b@x.com", "c@x.com"];
        await OpenCampaign(campaignId);
        await Queue(messageId, campaignId, recipients);

        await using var session = Store.QuerySession();
        var rows = await session.Query<DeliveryLog>().Where(x => x.MessageId == messageId).ToListAsync();

        rows.Count.ShouldBe(3);
        rows.Select(r => r.Recipient).OrderBy(r => r).ShouldBe(recipients);
        rows.Select(r => r.Id).OrderBy(r => r)
            .ShouldBe(recipients.Select(r => DeliveryLogProjection.Key(messageId, r)).OrderBy(r => r));

        // Every row carries the campaign, which the event did carry — so this is a copy, not a lookup.
        rows.ShouldAllBe(r => r.CampaignId == campaignId);
    }

    /// <summary>
    /// WHY <c>Options.DeleteViewTypeOnTeardown&lt;T&gt;()</c> IS NOT OPTIONAL, made observable.
    ///
    /// Because an EventProjection writes through ad-hoc ops.Store calls, Marten cannot infer which document
    /// type it produces — so without that declaration a rebuild does not clear the table first. The stale
    /// rows are then re-upserted over and nobody notices, because the ids that ARE regenerated look
    /// correct.
    ///
    /// This test plants a row that NO event produces and rebuilds. With the declaration the row is gone;
    /// without it, it survives a rebuild forever. Delete the constructor line in DeliveryLogProjection and
    /// this is the test that fails.
    /// </summary>
    [Fact]
    public async Task ARebuildOfAnEventProjectionClearsRowsNoEventProduces()
    {
        var campaignId = Guid.NewGuid();
        var messageId = Guid.NewGuid();
        await OpenCampaign(campaignId);
        await Queue(messageId, campaignId, ["a@x.com"]);

        const string orphanId = "not-from-any-event";
        await using (var session = Store.LightweightSession())
        {
            session.Store(new DeliveryLog
            {
                Id = orphanId, MessageId = Guid.NewGuid(), CampaignId = campaignId,
                Recipient = "ghost@x.com", Subject = "Never queued", QueuedAt = SeedData.SeededAt,
            });
            await session.SaveChangesAsync();
        }

        await using (var check = Store.QuerySession())
            (await check.LoadAsync<DeliveryLog>(orphanId)).ShouldNotBeNull("the orphan must exist first");

        using var daemon = await Store.BuildProjectionDaemonAsync();
        await daemon.RebuildProjectionAsync<DeliveryLogProjection>(DaemonTimeout, CancellationToken.None);

        await using var after = Store.QuerySession();
        (await after.LoadAsync<DeliveryLog>(orphanId)).ShouldBeNull();

        // And the real row is back, so the teardown did not just empty the table.
        (await after.LoadAsync<DeliveryLog>(DeliveryLogProjection.Key(messageId, "a@x.com")))
            .ShouldNotBeNull();
    }

    // =============================================================================================
    // RECIPE 4 — MultiStream across TWO stream types, Async, with a grouper
    // =============================================================================================

    /// <summary>
    /// One row built from two different KINDS of stream: Campaign events supply the name and status,
    /// Message events supply the counters. A single-stream projection cannot express this at all.
    ///
    /// Also the measurement of what Async costs. The elapsed wait is printed rather than asserted — an
    /// upper bound would be a timing assertion and those are how flaky suites get written. What IS
    /// asserted is that the wait is necessary API: nothing here reads the view without it.
    /// </summary>
    [Fact]
    public async Task ACampaignRowIsBuiltFromBothStreamTypes()
    {
        var campaignId = Guid.NewGuid();
        var first = Guid.NewGuid();
        var second = Guid.NewGuid();
        await OpenCampaign(campaignId, "Spans two streams");
        await Queue(first, campaignId, ["a@x.com", "b@x.com"]);
        await Queue(second, campaignId, ["c@x.com"]);
        await Outcome(first, "a@x.com", RecordOutcomeEndpoint.Delivered);
        await Outcome(first, "b@x.com", RecordOutcomeEndpoint.Bounced);

        var clock = Stopwatch.StartNew();
        await Store.WaitForNonStaleProjectionDataAsync(DaemonTimeout);
        clock.Stop();
        output.WriteLine($"async daemon caught up in {clock.ElapsedMilliseconds} ms");

        await using var session = Store.QuerySession();
        var row = await session.LoadAsync<CampaignDashboard>(campaignId);

        row.ShouldNotBeNull();
        row.Name.ShouldBe("Spans two streams");              // from the Campaign stream
        row.Status.ShouldBe(CampaignDashboard.Open);         // from event PRESENCE on the Campaign stream
        row.Queued.ShouldBe(2);                              // from two Message streams
        row.Delivered.ShouldBe(1);                           // from an event carrying NO campaignId
        row.Bounced.ShouldBe(1);                             // ditto
    }

    /// <summary>
    /// THE GROUPER, isolated. MessageDelivered carries messageId and recipient and nothing else — there is
    /// no campaignId anywhere in its payload. It still lands on the right campaign's row, and the only
    /// thing that can have put it there is the lookup the grouper reads.
    ///
    /// Two campaigns, so "it found the right one" is a real claim rather than "there was only one row".
    /// </summary>
    [Fact]
    public async Task AnOutcomeEventThatCarriesNoCampaignIdStillLandsOnTheRightCampaign()
    {
        var mine = Guid.NewGuid();
        var theirs = Guid.NewGuid();
        var myMessage = Guid.NewGuid();
        var theirMessage = Guid.NewGuid();

        await OpenCampaign(mine, "Mine");
        await OpenCampaign(theirs, "Theirs");
        await Queue(myMessage, mine, ["a@x.com"]);
        await Queue(theirMessage, theirs, ["b@x.com"]);

        // The event under test. Nothing about it says which campaign it belongs to.
        await Outcome(myMessage, "a@x.com", RecordOutcomeEndpoint.Delivered);

        await Store.WaitForNonStaleProjectionDataAsync(DaemonTimeout);

        await using var session = Store.QuerySession();
        (await session.LoadAsync<CampaignDashboard>(mine))!.Delivered.ShouldBe(1);
        (await session.LoadAsync<CampaignDashboard>(theirs))!.Delivered.ShouldBe(0);

        // The lookup that made it possible. Asserted because it is a MECHANISM that appears in no model,
        // and a reader finding an unexplained document type deserves to find a test naming it.
        (await session.LoadAsync<MessageCampaignLink>(myMessage))!.CampaignId.ShouldBe(mine);
    }

    /// <summary>
    /// The same-batch case the batch-aware grouper exists for. A MessageQueued and an outcome for the same
    /// message inside one daemon page: a grouper that only queried the lookup table would find no row yet,
    /// drop the outcome event silently, and leave the counter one short with nothing failing.
    ///
    /// Appended straight to the stream in one transaction, because that is the only way to guarantee they
    /// share a page — driving the endpoints produces two separate commits.
    /// </summary>
    [Fact]
    public async Task AnOutcomeArrivingInTHESAMEBatchAsItsQueueIsStillCounted()
    {
        var campaignId = Guid.NewGuid();
        var messageId = Guid.NewGuid();
        await OpenCampaign(campaignId);

        await Given(messageId,
            new MessageQueued(messageId, campaignId, Sender, "Subject", ["a@x.com"], SeedData.SeededAt),
            new MessageDelivered(messageId, "a@x.com", SeedData.SeededAt));

        await Store.WaitForNonStaleProjectionDataAsync(DaemonTimeout);

        await using var session = Store.QuerySession();
        var row = await session.LoadAsync<CampaignDashboard>(campaignId);

        row.ShouldNotBeNull();
        row.Queued.ShouldBe(1);
        row.Delivered.ShouldBe(1);   // the assertion that fails without step 1 of the grouper
    }

    // =============================================================================================
    // RECIPE 5 — MultiStream across MANY streams of ONE type, keyed by metadata
    // =============================================================================================

    /// <summary>
    /// A different problem from recipe 4's, and easy to conflate with it. Every event here is the same type
    /// from the same kind of stream; what is hard is that ONE ROW SPANS AN UNBOUNDED NUMBER of them.
    ///
    /// Three messages are three separate Message streams. They collapse into one (sender, month) row.
    /// </summary>
    [Fact]
    public async Task ManyStreamsOfOneTypeRollUpIntoOneRow()
    {
        var campaignId = Guid.NewGuid();
        var sender = Guid.NewGuid();
        await OpenCampaign(campaignId);

        await Queue(Guid.NewGuid(), campaignId, ["a@x.com", "b@x.com"], sender);
        await Queue(Guid.NewGuid(), campaignId, ["c@x.com"], sender);
        await Queue(Guid.NewGuid(), campaignId, ["d@x.com", "e@x.com", "f@x.com"], sender);

        // Inline, so no wait — that is the other half of the Inline/Async comparison, on the same shape of
        // projection as the Async one above.
        await using var session = Store.QuerySession();
        var key = SenderMonthlyProjection.Key(sender, DateTimeOffset.UtcNow);
        var row = await session.LoadAsync<SenderMonthly>(key);

        row.ShouldNotBeNull();
        row.SenderId.ShouldBe(sender);
        row.Messages.ShouldBe(3);
        row.Recipients.ShouldBe(6);

        // THE MONTH CAME FROM EVENT METADATA. No event in this system carries a month — the model could
        // only say derived="month=MessageQueued" — so any value here at all is proof it came from the
        // envelope's Timestamp rather than from a payload.
        //
        // And note WHICH month it is: the one the event was APPENDED in. That is what makes this assertion
        // pass against UtcNow even though every payload here would say otherwise on a backfill. Running the
        // app with seed data timestamped 2026-01 produced a row keyed 2026-08 — see SenderMonthly.cs.
        row.Month.ShouldBe($"{DateTimeOffset.UtcNow:yyyy-MM}");
        row.Id.ShouldBe($"{sender}:{row.Month}");
    }

    /// <summary>
    /// The other half of the grain: the rollup must SEPARATE as well as combine. Without this, a projection
    /// that put every message in the world on one row would pass the test above.
    /// </summary>
    [Fact]
    public async Task TwoSendersAreTwoRows()
    {
        var campaignId = Guid.NewGuid();
        var one = Guid.NewGuid();
        var two = Guid.NewGuid();
        await OpenCampaign(campaignId);

        await Queue(Guid.NewGuid(), campaignId, ["a@x.com"], one);
        await Queue(Guid.NewGuid(), campaignId, ["b@x.com"], two);
        await Queue(Guid.NewGuid(), campaignId, ["c@x.com"], two);

        await using var session = Store.QuerySession();
        var now = DateTimeOffset.UtcNow;

        (await session.LoadAsync<SenderMonthly>(SenderMonthlyProjection.Key(one, now)))!
            .Messages.ShouldBe(1);
        (await session.LoadAsync<SenderMonthly>(SenderMonthlyProjection.Key(two, now)))!
            .Messages.ShouldBe(2);
    }

    // =============================================================================================
    // RECIPE 6 — a read model that is a SQL table
    // =============================================================================================

    /// <summary>
    /// What the flat table is FOR. The question is "delivery rate per campaign", which is an aggregation
    /// ACROSS rows — a document store answers it by loading every row into memory, Postgres answers it
    /// with a GROUP BY. That is the entire reason to accept a second read model at the same grain as
    /// MessageStatus.
    ///
    /// Note there is no MessageMetrics C# type to load. The read model IS the table.
    /// </summary>
    [Fact]
    public async Task TheFlatTableAnswersAnAcrossRowsAggregationInSql()
    {
        var campaignId = Guid.NewGuid();
        var first = Guid.NewGuid();
        var second = Guid.NewGuid();
        await OpenCampaign(campaignId);
        await Queue(first, campaignId, ["a@x.com", "b@x.com"]);
        await Queue(second, campaignId, ["c@x.com"]);
        await Outcome(first, "a@x.com", RecordOutcomeEndpoint.Delivered);
        await Outcome(first, "b@x.com", RecordOutcomeEndpoint.Bounced);
        await Outcome(second, "c@x.com", RecordOutcomeEndpoint.Delivered);

        var (messages, delivered, bounced) = await CampaignTotals(campaignId);

        messages.ShouldBe(2);      // one row per message, created by the full-mapping event
        delivered.ShouldBe(2);     // Increment, across two different message rows
        bounced.ShouldBe(1);
    }

    /// <summary>
    /// The UPDATE-only behaviour of a partial-mapping event, which is a safety property rather than a
    /// limitation: MessageDelivered populates none of campaign_id / sender_id / queued_at, so Marten
    /// generates an UPDATE for it and it CANNOT create a half-filled row.
    ///
    /// Appended straight to the stream because no endpoint would allow it — the decider refuses an outcome
    /// for a message nobody queued, so this is a state only history can produce.
    /// </summary>
    [Fact]
    public async Task AnOutcomeForAMessageWithNoQueueEventIsANoOpNotAHalfRow()
    {
        var orphan = Guid.NewGuid();
        await Given(orphan, new MessageDelivered(orphan, "a@x.com", SeedData.SeededAt));

        await using var session = Store.QuerySession();
        await using var command = session.Connection!.CreateCommand();
        command.CommandText = $"select count(*) from campaigns.{MessageMetricsProjection.TableName} where id = $1";
        command.Parameters.Add(new NpgsqlParameter { Value = orphan });

        Convert.ToInt64(await command.ExecuteScalarAsync()).ShouldBe(0);
    }

    /// <summary>Reads the flat table the way any consumer of it would: in SQL.</summary>
    private async Task<(long Messages, long Delivered, long Bounced)> CampaignTotals(Guid campaignId)
    {
        await using var session = Store.QuerySession();
        await using var command = session.Connection!.CreateCommand();
        command.CommandText = $"""
            select count(*), coalesce(sum(delivered), 0), coalesce(sum(bounced), 0)
            from campaigns.{MessageMetricsProjection.TableName}
            where campaign_id = $1
            group by campaign_id
            """;
        command.Parameters.Add(new NpgsqlParameter { Value = campaignId });

        await using var reader = await command.ExecuteReaderAsync();
        if (!await reader.ReadAsync()) return (0, 0, 0);
        return (reader.GetInt64(0), reader.GetInt64(1), reader.GetInt64(2));
    }
}
